import{_ as a,o as t,c as n,a4 as p}from"./chunks/framework.DAD9IEko.js";const g=JSON.parse('{"title":"CE-08: 控制器设计的九大核心问题","description":"","frontmatter":{"date":"2026-06-06T00:00:00.000Z","section":"电机控制","chapter":"controllers-evolution","chapterTitle":"控制器演进","chapterOrder":50,"category":"控制器演进","source":"motor","visibility":"public","title":"CE-08: 控制器设计的九大核心问题","tags":["motor-control"],"status":"learning","summary":"**副标题：从PID到非线性MPC，每一代控制器都是对同一组根本问题的回答** **难度：**  中等 **适用对象：** 控制理论学习者、电机控制工程师 **前置知识：** CE-03（频域分析基础）","navGroup":"工程与生态","navGroupOrder":50},"headers":[],"relativePath":"content/motor/controllers-evolution/CE-08-Core-Problems.md","filePath":"content/motor/controllers-evolution/CE-08-Core-Problems.md","lastUpdated":1783181958000}'),m={name:"content/motor/controllers-evolution/CE-08-Core-Problems.md"};function e(l,s,i,r,o,c){return t(),n("div",null,[...s[0]||(s[0]=[p('<h1 id="ce-08-控制器设计的九大核心问题" tabindex="-1">CE-08: 控制器设计的九大核心问题 <a class="header-anchor" href="#ce-08-控制器设计的九大核心问题" aria-label="Permalink to &quot;CE-08: 控制器设计的九大核心问题&quot;">​</a></h1><p><strong>副标题：从PID到非线性MPC，每一代控制器都是对同一组根本问题的回答</strong><strong>难度：</strong> 中等 <strong>适用对象：</strong> 控制理论学习者、电机控制工程师 <strong>前置知识：</strong> CE-03（频域分析基础）</p><hr><h2 id="_1-核心摘要" tabindex="-1">1. 核心摘要 <a class="header-anchor" href="#_1-核心摘要" aria-label="Permalink to &quot;1.  核心摘要&quot;">​</a></h2><p>剥去数学外衣，每个控制系统面对的都是同一组横亘在&quot;完美跟踪&quot;与&quot;现实&quot;之间的障碍：测量噪声与延迟、被控对象的惯性与滞后、执行器的物理约束、模型的不确定性、外部扰动、非线性特性、稳定性保证、实时计算限制，以及多目标之间的不可调和的权衡。这九大问题不是彼此独立的——它们相互叠加、彼此恶化。理解这些问题，就是理解控制理论为什么沿着从PID到LQR到MPC的路径演化。</p><p><strong>认知挂钩：</strong> 火箭着陆同时激活了全部九个问题——噪声超音速GPS、巨大助推器惯性、发动机节流阀限制、不确定气动特性、阵风、非线性阻力、安全关键稳定性、毫秒级控制截止期、燃料与精度的竞争目标。没有任何单一技术能同时解决所有问题——这就是为什么工程控制器总是组合多种方案。</p><hr><h2 id="_2-概览" tabindex="-1">2. 概览 <a class="header-anchor" href="#_2-概览" aria-label="Permalink to &quot;2. 概览&quot;">​</a></h2><p>剥去数学外衣，每个控制系统面对的都是同一组横亘在你和完美跟踪之间的障碍。每个障碍催生了控制理论的一整个分支：</p><div class="kb-table-scroll"><table><thead><tr><th>#</th><th>问题</th><th>含义</th><th>催生的技术</th></tr></thead><tbody><tr><td>1</td><td><strong>测量</strong></td><td>你不知道真实状态——噪声、延迟、部分感知</td><td>卡尔曼滤波器（Kalman Filter）、Luenberger观测器、Smith预估器</td></tr><tr><td>2</td><td><strong>惯性/延迟</strong></td><td>被控对象不会立即响应——能量需要传递，质量需要加速</td><td>阻尼控制、基于模型的设计、前馈</td></tr><tr><td>3</td><td><strong>约束</strong></td><td>执行器有硬限制——电压、电流、力矩、变化率</td><td>约束优化、MPC、抗饱和（Anti-windup）</td></tr><tr><td>4</td><td><strong>模型不确定性</strong></td><td>模型总是错的——参数漂移、动力学未建模</td><td>鲁棒控制（H∞）、自适应控制、滑模控制</td></tr><tr><td>5</td><td><strong>扰动</strong></td><td>未知外力作用于被控对象——风、负载变化、摩擦</td><td>扰动观测器（DOB）、自抗扰控制（ADRC）、内模原理</td></tr><tr><td>6</td><td><strong>非线性</strong></td><td>现实世界不是线性的——摩擦、饱和、空气动力学</td><td>增益调度、反馈线性化、非线性MPC</td></tr><tr><td>7</td><td><strong>稳定性</strong></td><td>你需要保证系统不会崩溃</td><td>李亚普诺夫理论、无源性、小增益定理</td></tr><tr><td>8</td><td><strong>计算</strong></td><td>控制器必须在真实硬件上实时运行</td><td>显式MPC、热启动、高效QP求解器</td></tr><tr><td>9</td><td><strong>多目标权衡</strong></td><td>你不可能什么都要——速度 vs 超调、能量 vs 精度</td><td>Pareto最优控制、H₂/H∞权衡、Q/R整定</td></tr></tbody></table></div><p>这些问题不是孤立的。它们会叠加。火箭着陆同时激活了全部九个问题：噪声超音速GPS、巨大助推器惯性、发动机节流阀限制、不确定气动特性、阵风、非线性阻力、安全关键稳定性、毫秒级控制截止期、燃料与精度的竞争目标。没有任何单一技术能同时解决所有问题——这就是为什么工程控制器总是组合多种方案。</p><hr><h2 id="_3-测量——你不知道真实状态" tabindex="-1">3. 测量——你不知道真实状态 <a class="header-anchor" href="#_3-测量——你不知道真实状态" aria-label="Permalink to &quot;3. 测量——你不知道真实状态&quot;">​</a></h2><h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>控制器计算 <code>u = f(测量状态)</code>。但你手上的只有：</p><ul><li><strong>噪声：</strong> 传感器读数被污染——热噪声、量化、振动</li><li><strong>延迟：</strong> 测量迟到——传感器延迟、通信总线、计算时间</li><li><strong>部分测量：</strong> 你测量电机位置但不知道速度；房间温度只有一个点但不知道整个温度场</li></ul><p>把原始测量当作真实状态使用会产生错误的控制动作。更糟的是，对噪声信号做差分（例如对位置差分得到速度）会放大高频噪声。PID中的微分作用因此臭名昭著——这就是为什么很多工业PID回路只用到PI。</p><h3 id="解决方案-估计状态" tabindex="-1">解决方案：估计状态 <a class="header-anchor" href="#解决方案-估计状态" aria-label="Permalink to &quot;解决方案：估计状态&quot;">​</a></h3><p>核心思想：与被控对象<strong>并行运行一个模型</strong>，用测量值修正其状态。</p><p><strong>Luenberger观测器</strong>（1964）。运行被控对象模型的一个副本，加上修正项：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mover accent="true"><mi>x</mi><mo>^</mo></mover><mrow><mi>k</mi><mo>+</mo><mn>1</mn></mrow></msub><mo>=</mo><mi>A</mi><msub><mover accent="true"><mi>x</mi><mo>^</mo></mover><mi>k</mi></msub><mo>+</mo><mi>B</mi><msub><mi>u</mi><mi>k</mi></msub><mo>+</mo><mi>L</mi><mo stretchy="false">(</mo><msub><mi>y</mi><mi>k</mi></msub><mo>−</mo><mi>C</mi><msub><mover accent="true"><mi>x</mi><mo>^</mo></mover><mi>k</mi></msub><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\hat{x}_{k+1} = A \\hat{x}_k + B u_k + L (y_k - C \\hat{x}_k)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">x</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord mathnormal">A</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">x</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">L</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">x</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span><p>增益 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 通过极点配置设计——将观测器极点放在控制器极点2~5倍远的地方。<strong>分离原理（Separation Principle）</strong> 保证你可以独立设计估计器和控制器。</p><p><strong>卡尔曼滤波器（Kalman Filter）</strong>（1960）。同样的结构，但 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 是在给定统计噪声模型下<em>最优</em>选择的：</p><div class="kb-table-scroll"><table><thead><tr><th></th><th>控制（LQR）</th><th>估计（Kalman）</th></tr></thead><tbody><tr><td><strong>Riccati方向</strong></td><td>反向</td><td>正向</td></tr><tr><td><strong>权重</strong></td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span>（状态代价），<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi></mrow><annotation encoding="application/x-tex">R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>（控制代价）</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span>（过程噪声），<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi></mrow><annotation encoding="application/x-tex">R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>（测量噪声）</td></tr><tr><td><strong>最小化什么</strong></td><td>状态误差 + 控制代价</td><td>估计误差协方差</td></tr></tbody></table></div><p>卡尔曼 + LQR的组合就是 <strong>LQG</strong>——线性高斯系统的最优估计 + 最优控制。对偶性：估计和控制是同一套数学朝相反方向运行。</p><p><strong>Smith预估器</strong>（1957）。针对纯测量延迟 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>τ</mi></mrow><annotation encoding="application/x-tex">\\tau</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 的专用方案。运行一个<em>不含</em>延迟的模型用于反馈，加上延迟模型失配的修正项。最初为化工过程控制开发（管道传输延迟可达数分钟）。至今仍在使用。</p><h3 id="为什么这推动了控制器演进" tabindex="-1">为什么这推动了控制器演进 <a class="header-anchor" href="#为什么这推动了控制器演进" aria-label="Permalink to &quot;为什么这推动了控制器演进&quot;">​</a></h3><ul><li><strong>PID</strong> 假设测量 = 真实值。微分作用放大噪声；低通滤波是临时补丁。</li><li><strong>LQR</strong> 假设全状态反馈。实际中 → LQG（卡尔曼 + LQR）。</li><li><strong>MPC</strong> 通常在上游运行独立的估计器（卡尔曼滤波器、移动时域估计）。</li></ul><hr><h2 id="_4-惯性-延迟——被控对象不会立即响应" tabindex="-1">4. 惯性/延迟——被控对象不会立即响应 <a class="header-anchor" href="#_4-惯性-延迟——被控对象不会立即响应" aria-label="Permalink to &quot;4. 惯性/延迟——被控对象不会立即响应&quot;">​</a></h2><h3 id="问题-1" tabindex="-1">问题 <a class="header-anchor" href="#问题-1" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>给电机加电压，它不会瞬间达到目标转速——转子有惯性。打开阀门，液柱有动量。开启加热器，热质吸收能量。</p><p>惯性储存能量并随时间释放。从控制器角度看，这感觉就像延迟：你发出指令，过一会儿才有响应。</p><h3 id="为什么惯性本质上是延迟问题" tabindex="-1">为什么惯性本质上是延迟问题 <a class="header-anchor" href="#为什么惯性本质上是延迟问题" aria-label="Permalink to &quot;为什么惯性本质上是延迟问题&quot;">​</a></h3><p>相位滞后是共同机制：</p><ul><li>一阶滞后 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><mi>τ</mi><mi>s</mi><mo>+</mo><mn>1</mn><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">1/(\\tau s + 1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mord mathnormal">s</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span></span>：相位 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>→</mo><mo>−</mo><msup><mn>90</mn><mo>∘</mo></msup></mrow><annotation encoding="application/x-tex">\\to -90^\\circ</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7574em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">9</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span></span></span></span></li><li>二阶系统：相位 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>→</mo><mo>−</mo><msup><mn>180</mn><mo>∘</mo></msup></mrow><annotation encoding="application/x-tex">\\to -180^\\circ</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7574em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">18</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span></span></span></span></li><li>纯延迟 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>e</mi><mrow><mo>−</mo><mi>τ</mi><mi>s</mi></mrow></msup></mrow><annotation encoding="application/x-tex">e^{-\\tau s}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7713em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7713em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span><span class="mord mathnormal mtight">s</span></span></span></span></span></span></span></span></span></span></span></span>：相位无界线性下降</li></ul><p>三者以同样的方式破坏反馈稳定性。控制器推了一把，看不到响应，再推一把——等被控对象动起来时，控制器已经推过头了。超调、振荡、失稳。</p><h3 id="解决方案-阻尼-预测" tabindex="-1">解决方案：阻尼 + 预测 <a class="header-anchor" href="#解决方案-阻尼-预测" aria-label="Permalink to &quot;解决方案：阻尼 + 预测&quot;">​</a></h3><p><strong>阻尼</strong>——PID的微分项、LQR的速度惩罚（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>q</mi><mi>ω</mi></msub></mrow><annotation encoding="application/x-tex">q_\\omega</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">ω</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）、MPC的终端代价（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi></mrow><annotation encoding="application/x-tex">P</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span>）——说的都是同一件事：<em>到达之前先减速。</em></p><p><strong>前馈（Feedforward）</strong>——不等误差出现，直接计算<em>应该</em>产生期望输出的控制量：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>u</mi><mtext>ff</mtext></msub><mo>=</mo><msup><mi>G</mi><mrow><mo>−</mo><mn>1</mn></mrow></msup><mo stretchy="false">(</mo><mn>0</mn><mo stretchy="false">)</mo><mo>⋅</mo><mi>r</mi></mrow><annotation encoding="application/x-tex">u_{\\text{ff}} = G^{-1}(0) \\cdot r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ff</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord">0</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span>。PID的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>K</mi><mi>p</mi></msub><mi>r</mi></mrow><annotation encoding="application/x-tex">K_p r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 项是零阶前馈。更高阶的版本逆置完整的被控对象模型。</p><p><strong>预测</strong>——对于大惯性，纯反馈太慢。等你看到误差时已经来不及了。你必须预测被控对象要往哪里走。这就是MPC滚动时域的意义：它规划一条考虑被控对象迟缓性的轨迹。</p><h3 id="模型开始值得付出的阈值" tabindex="-1">模型开始值得付出的阈值 <a class="header-anchor" href="#模型开始值得付出的阈值" aria-label="Permalink to &quot;模型开始值得付出的阈值&quot;">​</a></h3><ul><li>小惯性 → 纯反馈就够了 → PID足够</li><li>中等惯性 → 需要阻尼 → 带微分的PID、LQR</li><li>大惯性 → 需要预测 → 基于模型的前馈、MPC</li><li>巨大惯性 + 延迟 → 完整预测 + 约束 → MPC + 观测器</li></ul><p>核心洞察：<strong>惯性让模型变得重要。</strong> 当被控对象响应快时，无知代价低。当它慢时，无知致命。</p><hr><h2 id="_5-约束——执行器有硬限制" tabindex="-1">5. 约束——执行器有硬限制 <a class="header-anchor" href="#_5-约束——执行器有硬限制" aria-label="Permalink to &quot;5. 约束——执行器有硬限制&quot;">​</a></h2><h3 id="问题-2" tabindex="-1">问题 <a class="header-anchor" href="#问题-2" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>每个物理执行器都会饱和：电压轨、电流额定值、力矩限制、温度上限、变化率。一个要求12V电源输出30V的控制器是在要求不可能的事。</p><h3 id="为什么简单的截断会失败" tabindex="-1">为什么简单的截断会失败 <a class="header-anchor" href="#为什么简单的截断会失败" aria-label="Permalink to &quot;为什么简单的截断会失败&quot;">​</a></h3><p>显而易见的修复——计算，然后截断——失败有三个原因：</p><ol><li><p><strong>控制器不知道自己已经饱和。</strong> 内部状态（积分器、估计器）假设指令的 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>u</mi></mrow><annotation encoding="application/x-tex">u</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">u</span></span></span></span> 已经施加。但被控对象收到的更少。模型发散。</p></li><li><p><strong>积分器饱和（Integrator Windup）。</strong> 积分项在饱和期间持续累积。当误差过零时，饱和的积分器导致巨大超调。抗饱和（Anti-windup）补丁了这个问题，但没有解决根因。</p></li><li><p><strong>约束最优解的结构不同。</strong> 当求解器知道约束存在时，它找到的是<em>结构上不同</em>的控制序列——提前减速，避免不必要的饱和。简单截断是裁剪；约束优化是绕路。</p></li></ol><h3 id="解决方案-把约束嵌入优化" tabindex="-1">解决方案：把约束嵌入优化 <a class="header-anchor" href="#解决方案-把约束嵌入优化" aria-label="Permalink to &quot;解决方案：把约束嵌入优化&quot;">​</a></h3><p>MPC在每个时间步求解一个二次规划（Quadratic Program, QP）：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><munder><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>u</mi></munder><mi>J</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>u</mi><mo stretchy="false">)</mo><mspace width="1em"></mspace><mtext>s.t.</mtext><mspace width="1em"></mspace><msub><mi>u</mi><mi>min</mi><mo>⁡</mo></msub><mo>≤</mo><mi>u</mi><mo>≤</mo><msub><mi>u</mi><mi>max</mi><mo>⁡</mo></msub></mrow><annotation encoding="application/x-tex">\\min_u J(x, u) \\quad \\text{s.t.} \\quad u_{\\min} \\leq u \\leq u_{\\max}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.45em;vertical-align:-0.7em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.4em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">u</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">min</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">u</span><span class="mclose">)</span><span class="mspace" style="margin-right:1em;"></span><span class="mord text"><span class="mord">s.t.</span></span><span class="mspace" style="margin-right:1em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">i</span><span class="mtight">n</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7719em;vertical-align:-0.136em;"></span><span class="mord mathnormal">u</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">a</span><span class="mtight">x</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span><p>约束进入优化，而不是后处理。求解器看到墙壁，规划绕过它。</p><p><strong>代价：</strong> LQR离线求解一次Riccati方程。MPC在线每个时间步求解一个QP。实时优化的历史——内点法、有效集法、算子分裂、热启动——就是让这足够快的历史。</p><hr><h2 id="_6-模型不确定性——模型总是错的" tabindex="-1">6. 模型不确定性——模型总是错的 <a class="header-anchor" href="#_6-模型不确定性——模型总是错的" aria-label="Permalink to &quot;6. 模型不确定性——模型总是错的&quot;">​</a></h2><h3 id="问题-3" tabindex="-1">问题 <a class="header-anchor" href="#问题-3" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>每个控制器都使用模型，显式的或隐式的。PID的模型是&quot;P、I、D三项能搞定&quot;。LQR的模型是A和B矩阵。MPC的模型是完整的预测动力学。</p><p>所有模型都是错的。参数漂移（电机电阻随温度升高，电池电压下降）。动力学被简化（柔性模态被当作刚体，摩擦被建模为线性粘性）。工作点变化（飞机在海平面 vs 40000英尺）。</p><p>为错误模型设计的最优控制器可能比为正确模型设计的次优控制器更差。这就是<strong>鲁棒性问题（Robustness Problem）</strong>。</p><h3 id="解决方案谱系" tabindex="-1">解决方案谱系 <a class="header-anchor" href="#解决方案谱系" aria-label="Permalink to &quot;解决方案谱系&quot;">​</a></h3><p><strong>鲁棒控制（Robust Control）</strong>（1980年代–）。设计控制器使其容忍指定的不确定性集合。如果真实被控对象在标称模型的某个有界扰动范围内，稳定性和性能得到保证。工具：H∞综合、μ综合、小增益定理、间隙度量。</p><p>H∞问题：找到一个控制器 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>K</mi></mrow><annotation encoding="application/x-tex">K</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span>，最小化不确定性集合中所有被控对象上从扰动到误差的最坏情况增益：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><munder><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>K</mi></munder><mo stretchy="false">∥</mo><msub><mi>T</mi><mrow><mi>z</mi><mi>w</mi></mrow></msub><msub><mo stretchy="false">∥</mo><mi mathvariant="normal">∞</mi></msub></mrow><annotation encoding="application/x-tex">\\min_K \\lVert T_{zw} \\lVert_\\infty</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.4943em;vertical-align:-0.7443em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.3557em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">min</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7443em;"><span></span></span></span></span></span><span class="mopen">∥</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.044em;">z</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen"><span class="mopen">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">∞</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span><p>这产生故意保守的控制器——它们用标称性能换取有保证的鲁棒性。</p><p><strong>自适应控制（Adaptive Control）</strong>（1950年代–）。与其为最坏情况不确定性设计，不如<em>在线估计参数</em>并更新控制器。模型参考自适应控制（MRAC, Model Reference Adaptive Control）：通过实时调整控制器增益迫使被控对象表现得像参考模型。自校正调节器：估计被控对象参数，重新计算控制器，应用。</p><p>权衡：鲁棒控制保证稳定性但保守。自适应控制可以达到更高性能但在瞬态期间有失稳风险（参数估计可能漂移，激励可能不足）。</p><p><strong>滑模控制（Sliding Mode Control）</strong>（1970年代–）。不同的哲学：不建模不确定性，<em>压制</em>它。施加不连续控制律迫使状态到达&quot;滑动面&quot;并保持在那里，无论有界不确定性如何。代价：颤振（Chattering，高频切换），机械系统对此深恶痛绝。</p><p><strong>增益调度（Gain Scheduling）。</strong> 实用的折中。在多个工作点设计控制器，根据测量的调度变量（空速、高度、温度）插值增益。在航空航天中广泛使用。理论上不优雅——设计点之间的稳定性没有保证——但它管用。</p><h3 id="为什么这很重要" tabindex="-1">为什么这很重要 <a class="header-anchor" href="#为什么这很重要" aria-label="Permalink to &quot;为什么这很重要&quot;">​</a></h3><p>为标称模型最优但对不确定性脆弱的控制器在实践中毫无用处。每个实际部署都在与鲁棒性搏斗。LQR的有保证裕度（≥60°相位裕度，∞增益裕度）是其被广泛采用的重要原因——它们是<em>自动的</em>，不需要设计者单独验证。</p><hr><h2 id="_7-扰动——世界在推回来" tabindex="-1">7. 扰动——世界在推回来 <a class="header-anchor" href="#_7-扰动——世界在推回来" aria-label="Permalink to &quot;7. 扰动——世界在推回来&quot;">​</a></h2><h3 id="问题-4" tabindex="-1">问题 <a class="header-anchor" href="#问题-4" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>扰动是你无法控制的外力：</p><ul><li>无人机上的阵风</li><li>电机上的负载力矩（机器人拾取零件）</li><li>电源电压波动</li><li>摩擦变化（磨损、温度）</li><li>传感器偏置随时间漂移</li></ul><p>扰动不同于测量噪声。噪声腐蚀你<em>看到的</em>。扰动腐蚀被控对象<em>做的</em>。卡尔曼滤波器处理测量噪声。它不处理意外的负载力矩——除非你把扰动建模为增广状态（这正是扰动观测器所做的）。</p><h3 id="解决方案-估计并抵消" tabindex="-1">解决方案：估计并抵消 <a class="header-anchor" href="#解决方案-估计并抵消" aria-label="Permalink to &quot;解决方案：估计并抵消&quot;">​</a></h3><p><strong>积分作用</strong>是最古老的扰动抑制技术。积分器累积持续误差并调整控制来抵消它。内模原理（Internal Model Principle）：要抑制一个扰动，控制器必须包含该扰动的模型。恒定扰动需要积分器（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi mathvariant="normal">/</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">1/s</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord mathnormal">s</span></span></span></span>）。正弦扰动需要谐振器（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ω</mi><mi mathvariant="normal">/</mi><mo stretchy="false">(</mo><msup><mi>s</mi><mn>2</mn></msup><mo>+</mo><msup><mi>ω</mi><mn>2</mn></msup><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\omega/(s^2 + \\omega^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mord">/</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>）。</p><p><strong>扰动观测器（DOB, Disturbance Observer）</strong>（1980年代–）。通过比较实际被控对象输出与模型预测来估计扰动：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mover accent="true"><mi>d</mi><mo>^</mo></mover><mo>=</mo><msubsup><mi>G</mi><mtext>model</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msubsup><mo stretchy="false">(</mo><mi>y</mi><mo stretchy="false">)</mo><mo>−</mo><mi>u</mi></mrow><annotation encoding="application/x-tex">\\hat{d} = G_{\\text{model}}^{-1}(y) - u</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9579em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9579em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">d</span></span><span style="top:-3.2634em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.0833em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1555em;vertical-align:-0.2914em;"></span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.4086em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">model</span></span></span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2914em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">u</span></span></span></span></span><p>将估计值前馈抵消。简单、有效，在运动控制中广泛使用（机器人关节、硬盘驱动器）。</p><p><strong>自抗扰控制（ADRC, Active Disturbance Rejection Control）</strong>（韩京清，1990年代）。用&quot;总扰动&quot;项扩展被控对象状态，将未知动力学、外力和非线性打包在一起。用扩张状态观测器（ESO, Extended State Observer）估计一切。用前馈抵消扰动。剩余动力学近似为纯积分链——控制起来轻而易举。ADRC在几乎不需要模型信息的情况下异常有效。</p><p><strong>前馈</strong>来自可测量的扰动源。如果你能测量扰动（风速、来料温度），在反馈回路看到误差之前就前馈预补偿。</p><h3 id="为什么这很重要-1" tabindex="-1">为什么这很重要 <a class="header-anchor" href="#为什么这很重要-1" aria-label="Permalink to &quot;为什么这很重要&quot;">​</a></h3><p>扰动抑制是区分玩具控制器和工业控制器的关键。PID的积分器是最小可行方案。ADRC和DOB更有原则。MPC可以将扰动模型纳入预测——但前提是扰动已知或可估计。</p><hr><h2 id="_8-非线性——现实世界不是线性的" tabindex="-1">8. 非线性——现实世界不是线性的 <a class="header-anchor" href="#_8-非线性——现实世界不是线性的" aria-label="Permalink to &quot;8. 非线性——现实世界不是线性的&quot;">​</a></h2><h3 id="问题-5" tabindex="-1">问题 <a class="header-anchor" href="#问题-5" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>每个物理系统都是非线性的。摩擦有静摩擦和库仑分量（不仅仅是线性粘性的）。气动阻力与 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>v</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">v^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 成正比。化学反应速率遵循Arrhenius方程（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>e</mi><mrow><mo>−</mo><mi>E</mi><mi mathvariant="normal">/</mi><mi>R</mi><mi>T</mi></mrow></msup></mrow><annotation encoding="application/x-tex">e^{-E/RT}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.888em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.888em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0576em;">E</span><span class="mord mtight">/</span><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span></span></span></span></span>）。晶体管饱和。齿轮有间隙。</p><p>线性控制理论在工作点附近有效（Taylor展开：小 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>θ</mi></mrow><annotation encoding="application/x-tex">\\theta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 时 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>≈</mo><mi>θ</mi></mrow><annotation encoding="application/x-tex">\\sin\\theta \\approx \\theta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mop">sin</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span>）。远离那个点，它失效。大攻角的飞行器、高速机器人、接近失控的化学反应器——线性假设崩溃。</p><h3 id="解决方案谱系-1" tabindex="-1">解决方案谱系 <a class="header-anchor" href="#解决方案谱系-1" aria-label="Permalink to &quot;解决方案谱系&quot;">​</a></h3><p><strong>增益调度</strong>（实用，广泛使用）。在许多工作点设计线性控制器，在它们之间插值。没有理论保证，但实践中管用（飞机飞行控制、发动机管理）。</p><p><strong>反馈线性化（Feedback Linearization）</strong>（1980年代–）。找到非线性变量替换和控制律使闭环系统恰好线性。然后对线性化系统应用线性控制理论。需要精确模型。模型不确定时失效。</p><p><strong>滑模控制</strong>（1970年代–）。不建模非线性。压制它。用高增益切换驱动状态到滑动面，然后滑向原点。对有界不确定性鲁棒。颤振是实际问题。</p><p><strong>反步法（Backstepping）</strong>（1990年代–）。对于&quot;严格反馈形式&quot;的系统（级联积分器，每级有非线性），从最内层回路向外递归设计李亚普诺夫函数和虚拟控制。系统化且构造性——与反馈线性化不同，它可以处理某些类别的不确定性。</p><p><strong>非线性MPC</strong>（2000年代–）。在线求解完整的非线性最优控制问题。每步最小化 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>J</mi></mrow><annotation encoding="application/x-tex">J</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span></span></span></span>，满足 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>x</mi><mrow><mi>k</mi><mo>+</mo><mn>1</mn></mrow></msub><mo>=</mo><mi>f</mi><mo stretchy="false">(</mo><msub><mi>x</mi><mi>k</mi></msub><mo separator="true">,</mo><msub><mi>u</mi><mi>k</mi></msub><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">x_{k+1} = f(x_k, u_k)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 和约束——使用DDP（微分动态规划）、SQP（序列二次规划）或直接配点法。计算昂贵但越来越实用（SpaceX火箭着陆、波士顿动力机器人）。</p><h3 id="为什么这很重要-2" tabindex="-1">为什么这很重要 <a class="header-anchor" href="#为什么这很重要-2" aria-label="Permalink to &quot;为什么这很重要&quot;">​</a></h3><p>非线性是前沿。PID、LQR和线性MPC处理接近平衡的系统。当系统在大范围状态空间中运动——摆起倒立摆、着陆火箭、激进机动——你需要非线性工具。从线性MPC到非线性MPC的演进镜像了从LQR到线性MPC的演进：每一步同时处理更多问题，代价是计算量。</p><hr><h2 id="_9-稳定性——你需要保证" tabindex="-1">9. 稳定性——你需要保证 <a class="header-anchor" href="#_9-稳定性——你需要保证" aria-label="Permalink to &quot;9. 稳定性——你需要保证&quot;">​</a></h2><h3 id="问题-6" tabindex="-1">问题 <a class="header-anchor" href="#问题-6" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>控制器在仿真中工作不够。你需要<em>证明</em>闭环系统不会崩溃，即使：</p><ul><li>模型是近似的（鲁棒稳定性）</li><li>系统从远离平衡点出发（吸引域）</li><li>存在扰动（输入到状态稳定性）</li><li>控制器在连续被控对象上以离散时间实现（采样数据稳定性）</li></ul><p>没有稳定性保证的控制器是隐患。PID可能被激进整定搞失稳——没有自动保护。这就是为什么LQR是革命性的：它<em>自动</em>保证60°相位裕度和无穷增益裕度，无论你选什么Q和R。</p><h3 id="解决方案-李亚普诺夫理论及其后继" tabindex="-1">解决方案：李亚普诺夫理论及其后继 <a class="header-anchor" href="#解决方案-李亚普诺夫理论及其后继" aria-label="Permalink to &quot;解决方案：李亚普诺夫理论及其后继&quot;">​</a></h3><p><strong>李亚普诺夫稳定性（Lyapunov Stability）</strong>（1892）。找到一个标量函数 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>V</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">V(x) &gt; 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>x</mi><mo mathvariant="normal">≠</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">x \\neq 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel"><span class="mrel"><span class="mord vbox"><span class="thinbox"><span class="rlap"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="inner"><span class="mord"><span class="mrel"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace nobreak"></span><span class="mrel">=</span></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 时），沿轨迹递减（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mover accent="true"><mi>V</mi><mo>˙</mo></mover><mo>&lt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\dot{V} &lt; 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9593em;vertical-align:-0.0391em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9202em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1389em;"><span class="mord">˙</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>）。如果这样的函数存在，原点稳定。这是几乎所有非线性稳定性分析的基础。</p><p>对于LQR，最优代价 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>V</mi><mo stretchy="false">(</mo><mi>x</mi><mo stretchy="false">)</mo><mo>=</mo><msup><mi>x</mi><mi>T</mi></msup><mi>P</mi><mi>x</mi></mrow><annotation encoding="application/x-tex">V(x) = x^T P x</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal">x</span></span></span></span> <em>就是</em>一个李亚普诺夫函数——Riccati方程保证它递减。这是控制理论中最优雅的结果之一：最优性蕴含稳定性。</p><p><strong>无源性（Passivity）</strong>（1970年代–）。如果被控对象是无源的（它不产生能量），控制器也是无源的，则互连稳定。基于无源性的控制设计控制器来塑造能量函数，特别适用于机械和电气系统。</p><p><strong>小增益定理（Small-Gain Theorem）</strong>（1960年代）。如果环路增益小于1，闭环稳定。这把Bode直觉（增益裕度）推广到非线性和互连系统。在鲁棒控制中大量使用。</p><p><strong>障碍函数（Barrier Functions）</strong>（2010年代–）。对于安全关键系统，稳定性不够——你需要保证状态永远不进入不安全区域。控制障碍函数（CBF, Control Barrier Functions）约束控制输入使系统保持在安全集中。与控制李亚普诺夫函数（CLF, Control Lyapunov Functions）结合，产生既稳定又安全的控制器——用于自动驾驶、足式机器人、无人机群。</p><h3 id="为什么这很重要-3" tabindex="-1">为什么这很重要 <a class="header-anchor" href="#为什么这很重要-3" aria-label="Permalink to &quot;为什么这很重要&quot;">​</a></h3><p>稳定性是不可谈判的。航空航天、医疗设备、自动驾驶——失败意味着死亡。从&quot;仿真中工作&quot;到&quot;可证明安全&quot;的进步是控制器设计中最困难也最重要的一步。这也是控制理论证明其价值的地方：没有李亚普诺夫，你只是在祈祷。</p><hr><h2 id="_10-计算——控制器也有限制" tabindex="-1">10. 计算——控制器也有限制 <a class="header-anchor" href="#_10-计算——控制器也有限制" aria-label="Permalink to &quot;10. 计算——控制器也有限制&quot;">​</a></h2><h3 id="问题-7" tabindex="-1">问题 <a class="header-anchor" href="#问题-7" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>控制器在真实硬件上运行，资源有限：</p><ul><li><strong>时间：</strong> 控制回路有截止期（1 ms、100 µs、10 µs）</li><li><strong>内存：</strong> 嵌入式微控制器只有KB级，不是GB级</li><li><strong>功耗：</strong> 电池供电设备不能跑重优化</li><li><strong>数值精度：</strong> 定点DSP、单精度浮点</li></ul><p>一个数学上完美但在1 ms回路中需要10 ms计算的控制器毫无用处。计算是控制器本身的约束。</p><h3 id="解决方案谱系-2" tabindex="-1">解决方案谱系 <a class="header-anchor" href="#解决方案谱系-2" aria-label="Permalink to &quot;解决方案谱系&quot;">​</a></h3><p><strong>离线预计算。</strong> LQR的吸引力在于Riccati方程离线求解一次——在线控制器只是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>u</mi><mo>=</mo><mo>−</mo><mi>K</mi><mi>x</mi></mrow><annotation encoding="application/x-tex">u = -Kx</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">u</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mord mathnormal">x</span></span></span></span>（一个点积）。这就是为什么LQR能在任何平台上运行。</p><p><strong>显式MPC（Explicit MPC）</strong>（2002）。离线为<em>所有可能的</em>状态预求解QP。结果是将状态空间划分为多面体区域，每个区域有预计算的仿射控制律 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>u</mi><mo>=</mo><msub><mi>K</mi><mi>i</mi></msub><mi>x</mi><mo>+</mo><msub><mi>b</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">u = K_i x + b_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">u</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">b</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。在线：找到状态在哪个区域（点定位），应用对应律。以LQR级在线代价处理约束。大问题复杂度爆炸（区域数量随时域指数增长）。</p><p><strong>热启动（Warm Starting）。</strong> 状态只变化一个时间步。上一步的最优控制序列与这步非常接近。从那里初始化求解器——通常减少80%以上的迭代。OSQP和DAQP都支持。</p><p><strong>高效求解器。</strong> QP求解器的选择主导在线计算量：</p><ul><li><strong>有效集法（Active-set methods）</strong>（qpOASES, DAQP）：迭代少，适合小问题</li><li><strong>内点法（Interior-point methods）</strong>（CVXOPT, ECOS）：迭代多但可预测</li><li><strong>算子分裂法（Operator splitting）</strong>（OSQP, SCS）：一阶方法，可认证，GPU友好</li></ul><p><strong>事件触发和自触发控制。</strong> 不以固定速率计算。只在状态变化足够大时才计算。在稀疏事件场景下平均计算量减少10–100倍。</p><p><strong>多速率控制。</strong> 快内环（电流控制）以100 kHz运行简单PI控制器。慢外环（位置MPC）以100 Hz运行。快环隐藏了慢环的延迟。</p><h3 id="为什么这很重要-4" tabindex="-1">为什么这很重要 <a class="header-anchor" href="#为什么这很重要-4" aria-label="Permalink to &quot;为什么这很重要&quot;">​</a></h3><p>&quot;在MATLAB中验证&quot;和&quot;在微控制器上运行&quot;之间的鸿沟是大多数学术控制器的坟墓。实时实现是一等设计约束，不是事后补充。这就是为什么PID存活了一个世纪——它的计算代价基本为零。</p><hr><h2 id="_11-多目标权衡——你不可能什么都要" tabindex="-1">11. 多目标权衡——你不可能什么都要 <a class="header-anchor" href="#_11-多目标权衡——你不可能什么都要" aria-label="Permalink to &quot;11. 多目标权衡——你不可能什么都要&quot;">​</a></h2><h3 id="问题-8" tabindex="-1">问题 <a class="header-anchor" href="#问题-8" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>每个控制器都在平衡竞争目标：</p><ul><li><strong>速度 vs 超调</strong>——更快的上升意味着更多超调（线性系统中的水床效应）</li><li><strong>跟踪 vs 能量</strong>——激进跟踪消耗功率（LQR的Q vs R编码了这一点）</li><li><strong>鲁棒性 vs 标称性能</strong>——为最坏情况不确定性设计牺牲最佳情况性能</li><li><strong>简单性 vs 最优性</strong>——PID简单但次优；非线性MPC接近最优但复杂</li><li><strong>探索 vs 利用</strong>——在学习型控制中，尝试新动作风险即时性能下降</li></ul><p>这些不仅仅是实现细节。它们是不可公度的（Incommensurable）——没有单一数字能捕捉&quot;好坏&quot;。你必须选择在每个Pareto前沿上坐在哪里。</p><h3 id="解决方案-让权衡显式化" tabindex="-1">解决方案：让权衡显式化 <a class="header-anchor" href="#解决方案-让权衡显式化" aria-label="Permalink to &quot;解决方案：让权衡显式化&quot;">​</a></h3><p><strong>LQR权重</strong>（Q, R）是控制理论中最优雅的权衡编码。<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 惩罚状态误差，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi></mrow><annotation encoding="application/x-tex">R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 惩罚控制代价。比值 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mi mathvariant="normal">/</mi><mi>R</mi></mrow><annotation encoding="application/x-tex">Q/R</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">Q</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 决定激进程度。Riccati解找到数学上最优的折中。你不需要<em>设计</em>折中——你声明你在乎什么，数学返回给定优先级下最好的控制器。</p><p><strong>多目标MPC。</strong> 不用标量代价，对多个目标用显式权重优化。某些公式使用字典序排序（安全第一，然后性能，然后舒适度）。其他使用约束优化（最小化能量，满足跟踪误差 ≤ ε）。</p><p><strong>H₂ / H∞权衡。</strong> H₂优化标称性能（期望行为）。H∞优化最坏情况鲁棒性。混合H₂/H∞设计平衡两者——良好的标称性能加上对指定不确定性界的鲁棒性保证。</p><p><strong>根本问题：</strong> 没有控制器能超越被控对象物理施加的权衡。Bode积分公式说灵敏度函数的积分是守恒的——在一个频率上降低误差会在另一个频率上增加。水床效应是自然法则，不是工程限制。好的控制器设计不是消除权衡，而是让权衡可见并审慎选择。</p><hr><h2 id="_12-这些问题如何交互" tabindex="-1">12. 这些问题如何交互 <a class="header-anchor" href="#_12-这些问题如何交互" aria-label="Permalink to &quot;12. 这些问题如何交互&quot;">​</a></h2><p>问题会叠加。每个问题都使其他问题更难：</p><div class="kb-table-scroll"><table><thead><tr><th>场景</th><th>测量</th><th>惯性</th><th>约束</th><th>模型不确定</th><th>扰动</th><th>非线性</th><th>你需要什么</th></tr></thead><tbody><tr><td>快速电机，好编码器，大功率放大器</td><td></td><td></td><td></td><td></td><td></td><td></td><td>PID</td></tr><tr><td>同上，噪声编码器</td><td></td><td></td><td></td><td></td><td></td><td></td><td>PI + 滤波器，或LQG</td></tr><tr><td>重型机械臂，好编码器</td><td></td><td></td><td></td><td></td><td></td><td></td><td>LQR + 前馈</td></tr><tr><td>重型机械臂，变负载</td><td></td><td></td><td></td><td></td><td></td><td></td><td>LQR + 扰动观测器</td></tr><tr><td>电压严格受限的电机</td><td></td><td></td><td></td><td></td><td></td><td></td><td>MPC 或 PID + 抗饱和</td></tr><tr><td>老化电池（参数变化）</td><td></td><td></td><td></td><td></td><td></td><td></td><td>自适应MPC</td></tr><tr><td>风力涡轮机（柔性、阵风）</td><td></td><td></td><td></td><td></td><td></td><td></td><td>增益调度鲁棒MPC</td></tr><tr><td>火箭着陆</td><td></td><td></td><td></td><td></td><td></td><td></td><td>非线性MPC + EKF</td></tr></tbody></table></div><h3 id="分离原理在哪里崩溃" tabindex="-1">分离原理在哪里崩溃 <a class="header-anchor" href="#分离原理在哪里崩溃" aria-label="Permalink to &quot;分离原理在哪里崩溃&quot;">​</a></h3><p>分离原理（估计器 + 控制器独立设计 = 稳定的组合系统）对线性系统成立。它在以下情况下崩溃：</p><ul><li><strong>约束激活</strong>——控制器没有施加它说的量。估计器假设它施加了。估计发散。</li><li><strong>模型错误</strong>——估计器和控制器使用同一个错误模型。误差相关并放大。</li><li><strong>系统非线性</strong>——非线性系统没有一般的分离原理。</li></ul><p>这就是为什么约束MPC + 卡尔曼滤波器可能在两个组件分别完美调优的情况下仍然失败。也是鲁棒MPC和移动时域估计（MHE）是活跃研究领域的原因——它们显式处理交互。</p><hr><h2 id="_13-演化弧线" tabindex="-1">13. 演化弧线 <a class="header-anchor" href="#_13-演化弧线" aria-label="Permalink to &quot;13. 演化弧线&quot;">​</a></h2><p>控制理论不是随机演化的。每一代都是它能处理的问题集合增长的回应：</p><div class="kb-table-scroll"><table><thead><tr><th>代际</th><th>测量</th><th>惯性</th><th>约束</th><th>模型不确定</th><th>扰动</th><th>非线性</th><th>核心工具</th></tr></thead><tbody><tr><td><strong>PID</strong>（1920年代–）</td><td>假设干净</td><td>D项阻尼</td><td>抗饱和（补丁）</td><td>手动重整定</td><td>积分器</td><td>无</td><td>三项误差反馈</td></tr><tr><td><strong>LQR/LQG</strong>（1960年代–）</td><td>卡尔曼滤波</td><td>Riccati → 最优阻尼</td><td>无</td><td>有保证裕度（自动）</td><td>积分器（LQI）</td><td>无</td><td>状态空间、Riccati</td></tr><tr><td><strong>鲁棒</strong>（1980年代–）</td><td>H∞估计</td><td>结构化不确定性</td><td>纳入设计</td><td><strong>核心焦点</strong></td><td>H∞扰动衰减</td><td>小增益定理</td><td>H∞综合、μ综合</td></tr><tr><td><strong>自适应</strong>（1950–90年代）</td><td>在线参数估计</td><td>适应惯性变化</td><td>可适应饱和限制</td><td><strong>核心焦点</strong></td><td>估计并抵消</td><td>某些类别（MRAC）</td><td>在线估计、MRAC</td></tr><tr><td><strong>QP-MPC</strong>（1980年代–）</td><td>独立估计器</td><td>时域预测</td><td><strong>核心焦点</strong></td><td>Min-max变体</td><td>可测扰动模型</td><td>无（仅线性）</td><td>滚动时域QP</td></tr><tr><td><strong>非线性MPC</strong>（2000年代–）</td><td>移动时域估计</td><td>非线性预测</td><td>非线性约束</td><td>鲁棒NMPC变体</td><td>扰动模型</td><td><strong>核心焦点</strong></td><td>DDP、SQP、实时迭代</td></tr><tr><td><strong>学习型</strong>（2010年代–）</td><td>学习观测</td><td>学习动力学</td><td>学习安全滤波</td><td>学习不确定性集</td><td>学习扰动模式</td><td><strong>隐式处理</strong></td><td>RL、GP-MPC、神经ODE</td></tr></tbody></table></div><p>演进方向是同时处理更多问题，用计算量支付。1960年无法在1 kHz求解QP。2020年可以。问题永远是：<em>给定我的系统实际面临的问题，能处理它们的最简控制器是什么？</em></p><p>大多数系统不需要完整技术栈。慢动态、宽松规格的温度控制器用PI就行。汽车发动机需要增益调度MPC。火箭着陆需要一切。</p><hr><h2 id="_14-延伸阅读" tabindex="-1">14. 延伸阅读 <a class="header-anchor" href="#_14-延伸阅读" aria-label="Permalink to &quot;14. 延伸阅读&quot;">​</a></h2><p><strong>综合：</strong></p><ul><li>Åström, K.J. &amp; Murray, R.M. (2021). <em>Feedback Systems.</em> Princeton. — 覆盖全貌的最佳单卷入门。</li></ul><p><strong>测量：</strong></p><ul><li>Simon, D. (2006). <em>Optimal State Estimation.</em> Wiley. — 卡尔曼滤波、EKF、UKF、粒子滤波。</li><li>Smith, O.J.M. (1957). &quot;Closer control of loops with dead time.&quot; <em>Chemical Engineering Progress.</em></li></ul><p><strong>模型不确定性：</strong></p><ul><li>Zhou, K., Doyle, J.C., Glover, K. (1996). <em>Robust and Optimal Control.</em> Prentice-Hall. — H∞、μ综合，权威参考。</li><li>Åström, K.J. &amp; Wittenmark, B. (2013). <em>Adaptive Control.</em> Dover. — MRAC、自校正调节器。</li></ul><p><strong>扰动：</strong></p><ul><li>Han, J. (2009). &quot;From PID to Active Disturbance Rejection Control.&quot; <em>IEEE Trans. Industrial Electronics.</em></li><li>Chen, W.H. et al. (2016). &quot;Disturbance Observer-Based Control.&quot; <em>IEEE Trans. Industrial Electronics.</em></li></ul><p><strong>非线性：</strong></p><ul><li>Khalil, H.K. (2015). <em>Nonlinear Control.</em> Pearson. — 李亚普诺夫、反馈线性化、滑模、反步法。</li><li>Slotine, J.J. &amp; Li, W. (1991). <em>Applied Nonlinear Control.</em> Prentice-Hall.</li></ul><p><strong>约束：</strong></p><ul><li>Rawlings, J.B., Mayne, D.Q., Diehl, M. (2017). <em>Model Predictive Control: Theory, Computation, and Design.</em> Nob Hill.</li></ul><p><strong>稳定性与安全：</strong></p><ul><li>Sontag, E.D. (1998). <em>Mathematical Control Theory.</em> Springer. — 李亚普诺夫理论、输入到状态稳定性。</li><li>Ames, A.D. et al. (2019). &quot;Control Barrier Functions.&quot; <em>Annual Review of Control, Robotics, and Autonomous Systems.</em></li></ul><p><strong>本项目（相关文档）：</strong></p><ul><li><code>bellman_to_lqr.md</code> — 从动态规划到Riccati推导</li><li><code>care_vs_dare.md</code> — 离散 vs 连续Riccati</li><li><code>from_lp_to_qp_to_lqr.md</code> — MPC之下的优化引擎</li><li><code>nonlinear_mpc.md</code> — 动力学非线性后会发生什么</li><li><code>trajectory_tracking_lqr_mpc.md</code> — 跟踪 vs 调节</li><li><code>poles_zeros_ode.md</code> — 动力学的传递函数视角</li></ul>',174)])])}const d=a(m,[["render",e]]);export{g as __pageData,d as default};
